"""end_interview: mark the interview complete (the report is generated by POST .../end)."""

from typing import Any

from pydantic import BaseModel

from vox_api.agent.tools.base import Tool, ToolContext


class EndIn(BaseModel):
    pass


async def handler(args: EndIn, ctx: ToolContext) -> dict[str, Any]:
    iv = ctx.interview
    if iv is None:
        return {"error": "No active interview"}
    iv.current_question_index += 1
    iv.status = "complete"
    await ctx.db.flush()
    return {"status": "complete"}


TOOL = Tool(
    name="end_interview",
    description=(
        "End the interview. Call this when the candidate asks to stop, the planned questions are "
        "exhausted, or you have delivered a closing summary."
    ),
    input_model=EndIn,
    handler=handler,
)
